import { Body, Controller, Delete, Get, HttpCode, HttpStatus, Param, Post, Put, Query } from '@nestjs/common';
import { ApiTags } from '@nestjs/swagger';
import type { AuthDto } from 'src/dtos/auth.dto.js';
import { Endpoint, HistoryBuilder } from 'src/decorators.js';
import {
  AssetFaceCreateDto,
  AssetFaceDeleteDto,
  AssetFaceResponseDto,
  FaceDto,
  PersonResponseDto,
} from 'src/dtos/person.dto.js';
import { ApiTag, Permission } from 'src/enum.js';
import { Auth, Authenticated } from 'src/middleware/auth.guard.js';
import { PersonService } from 'src/services/person.service.js';
import { UUIDParamDto } from 'src/validation.js';

@ApiTags(ApiTag.Faces)
@Controller('faces')
export class FaceController {
  constructor(private service: PersonService) {}

  @Post()
  @Authenticated({ permission: Permission.FaceCreate })
  @Endpoint({
    summary: 'Create a face',
    description:
      'Create a new face that has not been discovered by facial recognition. The content of the bounding box is considered a face.',
    history: new HistoryBuilder().added('v1').beta('v1').stable('v2'),
  })
  createFace(@Auth() auth: AuthDto, @Body() dto: AssetFaceCreateDto) {
    return this.service.createFace(auth, dto);
  }

  @Get()
  @Authenticated({ permission: Permission.FaceRead })
  @Endpoint({
    summary: 'Retrieve faces for asset',
    description: 'Retrieve all faces belonging to an asset.',
    history: new HistoryBuilder().added('v1').beta('v1').stable('v2'),
  })
  getFaces(@Auth() auth: AuthDto, @Query() dto: FaceDto): Promise<AssetFaceResponseDto[]> {
    return this.service.getFacesById(auth, dto);
  }

  @Put(':id')
  @Authenticated({ permission: Permission.FaceUpdate })
  @Endpoint({
    summary: 'Re-assign a face to another person',
    description: 'Re-assign the face provided in the body to the person identified by the id in the path parameter.',
    history: new HistoryBuilder().added('v1').beta('v1').stable('v2'),
  })
  reassignFacesById(
    @Auth() auth: AuthDto,
    @Param() { id }: UUIDParamDto,
    @Body() dto: FaceDto,
  ): Promise<PersonResponseDto> {
    return this.service.reassignFacesById(auth, id, dto);
  }

  @Delete(':id')
  @Authenticated({ permission: Permission.FaceDelete })
  @HttpCode(HttpStatus.NO_CONTENT)
  @Endpoint({
    summary: 'Delete a face',
    description: 'Delete a face identified by the id. Optionally can be force deleted.',
    history: new HistoryBuilder().added('v1').beta('v1').stable('v2'),
  })
  deleteFace(@Auth() auth: AuthDto, @Param() { id }: UUIDParamDto, @Body() dto: AssetFaceDeleteDto): Promise<void> {
    return this.service.deleteFace(auth, id, dto);
  }
}

from typing import Any

import numpy as np
from numpy.typing import NDArray
from PIL import Image

from immich_ml.config import settings
from immich_ml.models.base import InferenceModel
from immich_ml.models.transforms import decode_pil, normalize, serialize_np_array
from immich_ml.schemas import (
    FaceDetectionOutput,
    FaceRecognitionOptions,
    FacialRecognitionOutput,
    ModelSource,
    ModelTask,
    ModelType,
    Shape,
)
from immich_ml.sessions.policy import ShapePolicy, batches, runs

from ._ops import ALIGNED_SIZE, align_face


class FaceRecognizer(InferenceModel[FaceRecognitionOptions]):
    depends = [(ModelType.DETECTION, ModelTask.FACIAL_RECOGNITION)]
    identity = (ModelType.RECOGNITION, ModelTask.FACIAL_RECOGNITION)
    sources = (ModelSource.INSIGHTFACE,)

    def __init__(self, model_name: str, **model_kwargs: Any) -> None:
        super().__init__(model_name, **model_kwargs)
        sizes = batches(settings.max_batch_size.facial_recognition)
        self.shape_policy = ShapePolicy(dims=tuple(Shape(batch) for batch in sizes))

    def _predict(
        self,
        inputs: NDArray[np.uint8] | bytes | Image.Image,
        faces: FaceDetectionOutput,
        options: FaceRecognitionOptions,
    ) -> FacialRecognitionOutput:
        if faces["boxes"].shape[0] == 0:
            return []
        image = np.asarray(decode_pil(inputs), dtype=np.uint8)
        landmarks = faces["landmarks"]
        sizes = runs(len(landmarks), self.session.batches)
        crops: NDArray[np.float32] | NDArray[np.uint8] = np.empty(
            (len(landmarks), ALIGNED_SIZE, ALIGNED_SIZE, 3), dtype=np.uint8
        )
        for crop, kps in zip(crops, landmarks):
            align_face(image, kps, crop)
        if not self.session.for_shape(Shape(sizes[0])).normalizes_input:
            crops = normalize(crops.transpose(0, 3, 1, 2).astype(np.float32, order="C"), mean=127.5, std=127.5)
        embeddings = self._predict_batch(crops, sizes)
        return self.postprocess(faces, embeddings)

    def _predict_batch(self, crops: NDArray[np.float32] | NDArray[np.uint8], sizes: list[int]) -> NDArray[np.float32]:
        embeddings = []
        start = 0
        for size in sizes:
            session = self.session.for_shape(Shape(size))
            embeddings.append(session.run(None, {session.get_inputs()[0].name: crops[start : start + size]})[0])
            start += size
        return embeddings[0] if len(embeddings) == 1 else np.concatenate(embeddings, axis=0)

    def postprocess(self, faces: FaceDetectionOutput, embeddings: NDArray[np.float32]) -> FacialRecognitionOutput:
        return [
            {
                "boundingBox": {"x1": x1, "y1": y1, "x2": x2, "y2": y2},
                "embedding": serialize_np_array(embedding),
                "score": score,
            }
            for (x1, y1, x2, y2), embedding, score in zip(faces["boxes"], embeddings, faces["scores"])
        ]

import { Injectable } from '@nestjs/common';
import { Duration } from 'luxon';
import { readFile } from 'node:fs/promises';
import { MachineLearningConfig } from 'src/dtos/config.dto.js';
import { LoggingRepository } from 'src/repositories/logging.repository.js';

export interface BoundingBox {
  x1: number;
  y1: number;
  x2: number;
  y2: number;
}

export enum ModelTask {
  FACIAL_RECOGNITION = 'facial-recognition',
  SEARCH = 'clip',
  OCR = 'ocr',
}

export enum ModelType {
  DETECTION = 'detection',
  PIPELINE = 'pipeline',
  RECOGNITION = 'recognition',
  TEXTUAL = 'textual',
  VISUAL = 'visual',
  OCR = 'ocr',
}

export type ModelPayload = { imagePath: string } | { text: string };

type ModelOptions = { modelName: string };

export type FaceDetectionOptions = ModelOptions & { minScore: number };
export type OcrOptions = ModelOptions & {
  minDetectionScore: number;
  minRecognitionScore: number;
  maxResolution: number;
};
type VisualResponse = { imageHeight: number; imageWidth: number };
export type ClipVisualRequest = { [ModelTask.SEARCH]: { [ModelType.VISUAL]: ModelOptions } };
export type ClipVisualResponse = { [ModelTask.SEARCH]: string } & VisualResponse;

export type ClipTextualRequest = { [ModelTask.SEARCH]: { [ModelType.TEXTUAL]: ModelOptions } };
export type ClipTextualResponse = { [ModelTask.SEARCH]: string };

export type OCR = {
  text: string[];
  box: number[];
  boxScore: number[];
  textScore: number[];
};

export type OcrRequest = {
  [ModelTask.OCR]: {
    [ModelType.DETECTION]: ModelOptions & { options: { minScore: number; maxResolution: number } };
    [ModelType.RECOGNITION]: ModelOptions & { options: { minScore: number } };
  };
};
export type OcrResponse = { [ModelTask.OCR]: OCR } & VisualResponse;

export type FacialRecognitionRequest = {
  [ModelTask.FACIAL_RECOGNITION]: {
    [ModelType.DETECTION]: ModelOptions & { options: { minScore: number } };
    [ModelType.RECOGNITION]: ModelOptions;
  };
};

export interface Face {
  boundingBox: BoundingBox;
  embedding: string;
  score: number;
}

export type FacialRecognitionResponse = { [ModelTask.FACIAL_RECOGNITION]: Face[] } & VisualResponse;
export type MachineLearningRequest = ClipVisualRequest | ClipTextualRequest | FacialRecognitionRequest | OcrRequest;
export type TextEncodingOptions = ModelOptions & { language?: string };

@Injectable()
export class MachineLearningRepository {
  private healthyMap: Record<string, boolean> = {};
  private interval?: ReturnType<typeof setInterval>;
  private _config?: MachineLearningConfig;

  private get config(): MachineLearningConfig {
    if (!this._config) {
      throw new Error('Machine learning repository not been setup');
    }

    return this._config;
  }

  constructor(private logger: LoggingRepository) {
    this.logger.setContext(MachineLearningRepository.name);
  }

  setup(config: MachineLearningConfig) {
    this._config = config;
    this.teardown();

    // delete old servers
    for (const url of Object.keys(this.healthyMap)) {
      if (!config.urls.includes(url)) {
        delete this.healthyMap[url];
      }
    }

    if (!config.enabled || !config.availabilityChecks.enabled) {
      return;
    }

    this.tick();
    this.interval = setInterval(
      () => this.tick(),
      Duration.fromObject({ milliseconds: config.availabilityChecks.interval }).as('milliseconds'),
    );
  }

  teardown() {
    if (this.interval) {
      clearInterval(this.interval);
    }
  }

  private tick() {
    for (const url of this.config.urls) {
      void this.check(url);
    }
  }

  private async check(url: string) {
    let isHealthy = false;
    try {
      const response = await fetch(new URL('ping', url), {
        signal: AbortSignal.timeout(this.config.availabilityChecks.timeout),
      });
      if (response.ok) {
        isHealthy = true;
      }
    } catch {
      // nothing to do here
    }

    this.setHealthy(url, isHealthy);
  }

  private setHealthy(url: string, healthy: boolean) {
    if (this.healthyMap[url] !== healthy) {
      this.logger.log(`Machine learning server became ${healthy ? 'healthy' : 'unhealthy'} (${url}).`);
    }

    this.healthyMap[url] = healthy;
  }

  private isHealthy(url: string) {
    if (!this.config.availabilityChecks.enabled) {
      return true;
    }

    return this.healthyMap[url];
  }

  private async predict<T>(payload: ModelPayload, config: MachineLearningRequest): Promise<T> {
    const formData = await this.getFormData(payload, config);

    for (const url of [
      // try healthy servers first
      ...this.config.urls.filter((url) => this.isHealthy(url)),
      ...this.config.urls.filter((url) => !this.isHealthy(url)),
    ]) {
      try {
        const response = await fetch(new URL('predict', url), { method: 'POST', body: formData });
        if (response.ok) {
          this.setHealthy(url, true);
          return response.json();
        }

        this.logger.warn(
          `Machine learning request to "${url}" failed with status ${response.status}: ${response.statusText}`,
        );
      } catch (error: Error | unknown) {
        this.logger.warn(`Machine learning request to "${url}" failed`, error);
      }

      this.setHealthy(url, false);
    }

    throw new Error(`Machine learning request '${JSON.stringify(config)}' failed for all URLs`);
  }

  async detectFaces(imagePath: string, { modelName, minScore }: FaceDetectionOptions) {
    const request = {
      [ModelTask.FACIAL_RECOGNITION]: {
        [ModelType.DETECTION]: { modelName, options: { minScore } },
        [ModelType.RECOGNITION]: { modelName },
      },
    };
    const response = await this.predict<FacialRecognitionResponse>({ imagePath }, request);
    return {
      imageHeight: response.imageHeight,
      imageWidth: response.imageWidth,
      faces: response[ModelTask.FACIAL_RECOGNITION],
    };
  }

  async encodeImage(imagePath: string, { modelName }: MachineLearningConfig['clip']) {
    const request = { [ModelTask.SEARCH]: { [ModelType.VISUAL]: { modelName } } };
    const response = await this.predict<ClipVisualResponse>({ imagePath }, request);
    return response[ModelTask.SEARCH];
  }

  async encodeText(text: string, { language, modelName }: TextEncodingOptions) {
    const request = { [ModelTask.SEARCH]: { [ModelType.TEXTUAL]: { modelName, options: { language } } } };
    const response = await this.predict<ClipTextualResponse>({ text }, request);
    return response[ModelTask.SEARCH];
  }

  async ocr(imagePath: string, { modelName, minDetectionScore, minRecognitionScore, maxResolution }: OcrOptions) {
    const request = {
      [ModelTask.OCR]: {
        [ModelType.DETECTION]: { modelName, options: { minScore: minDetectionScore, maxResolution } },
        [ModelType.RECOGNITION]: { modelName, options: { minScore: minRecognitionScore } },
      },
    };
    const response = await this.predict<OcrResponse>({ imagePath }, request);
    return response[ModelTask.OCR];
  }

  private async getFormData(payload: ModelPayload, config: MachineLearningRequest): Promise<FormData> {
    const formData = new FormData();
    formData.append('entries', JSON.stringify(config));

    if ('imagePath' in payload) {
      const fileBuffer = await readFile(payload.imagePath);
      formData.append('image', new Blob([new Uint8Array(fileBuffer)]));
    } else if ('text' in payload) {
      formData.append('text', payload.text);
    } else {
      throw new Error('Invalid input');
    }

    return formData;
  }
}

import { expect, Page, test } from '@playwright/test';
import { SeededRandom, selectRandom, TimelineAssetConfig } from 'src/ui/generators/timeline.js';
import {
  createMockPeople,
  FaceCreateCapture,
  MockPerson,
  setupFaceEditorMockApiRoutes,
} from 'src/ui/mock-network/face-editor-network';
import { assetViewerUtils } from '../timeline/utils';
import { setupAssetViewerFixture } from './utils';

const waitForSelectorTransition = async (page: Page) => {
  await page.waitForFunction(
    () => {
      const selector = document.querySelector('#face-selector') as HTMLElement | null;
      if (!selector) {
        return false;
      }
      return selector.getAnimations({ subtree: false }).every((animation) => animation.playState === 'finished');
    },
    undefined,
    { timeout: 1000, polling: 50 },
  );
};

const openFaceEditor = async (page: Page, asset: TimelineAssetConfig) => {
  await page.goto(`/photos/${asset.id}`);
  await assetViewerUtils.waitForViewerLoad(page, asset);
  await page.keyboard.press('i');
  await page.locator('#detail-panel').waitFor({ state: 'visible' });
  await page.getByLabel('Tag people').click();
  await page.locator('#face-selector').waitFor({ state: 'visible' });
  await waitForSelectorTransition(page);
};

test.describe.configure({ mode: 'parallel' });
test.describe('face-editor', () => {
  const fixture = setupAssetViewerFixture(777);
  const rng = new SeededRandom(777);
  let mockPeople: MockPerson[];
  let faceCreateCapture: FaceCreateCapture;

  test.beforeAll(async () => {
    mockPeople = createMockPeople(8);
  });

  test.beforeEach(async ({ context }) => {
    faceCreateCapture = { requests: [] };
    await setupFaceEditorMockApiRoutes(context, mockPeople, faceCreateCapture);
  });

  type ScreenRect = { top: number; left: number; width: number; height: number };

  const getFaceBoxRect = async (page: Page): Promise<ScreenRect> => {
    const dataEl = page.locator('#face-editor-data');
    await expect(dataEl).toHaveAttribute('data-face-left', /^-?\d+/);
    await expect(dataEl).toHaveAttribute('data-face-top', /^-?\d+/);
    await expect(dataEl).toHaveAttribute('data-face-width', /^[1-9]/);
    await expect(dataEl).toHaveAttribute('data-face-height', /^[1-9]/);
    const canvasBox = await page.locator('#face-editor').boundingBox();
    if (!canvasBox) {
      throw new Error('Canvas element not found');
    }
    const left = Number(await dataEl.getAttribute('data-face-left'));
    const top = Number(await dataEl.getAttribute('data-face-top'));
    const width = Number(await dataEl.getAttribute('data-face-width'));
    const height = Number(await dataEl.getAttribute('data-face-height'));
    return {
      top: canvasBox.y + top,
      left: canvasBox.x + left,
      width,
      height,
    };
  };

  const getSelectorRect = async (page: Page): Promise<ScreenRect> => {
    const box = await page.locator('#face-selector').boundingBox();
    if (!box) {
      throw new Error('Face selector element not found');
    }
    return { top: box.y, left: box.x, width: box.width, height: box.height };
  };

  const computeOverlapArea = (a: ScreenRect, b: ScreenRect): number => {
    const overlapX = Math.max(0, Math.min(a.left + a.width, b.left + b.width) - Math.max(a.left, b.left));
    const overlapY = Math.max(0, Math.min(a.top + a.height, b.top + b.height) - Math.max(a.top, b.top));
    return overlapX * overlapY;
  };

  const dragFaceBox = async (page: Page, deltaX: number, deltaY: number) => {
    const faceBox = await getFaceBoxRect(page);
    const centerX = faceBox.left + faceBox.width / 2;
    const centerY = faceBox.top + faceBox.height / 2;
    await page.mouse.move(centerX, centerY);
    await page.mouse.down();
    await page.mouse.move(centerX + deltaX, centerY + deltaY, { steps: 5 });
    await page.mouse.up();
    await page.waitForTimeout(300);
  };

  test('Face editor opens with person list', async ({ page }) => {
    const asset = selectRandom(fixture.assets, rng);
    await openFaceEditor(page, asset);

    await expect(page.locator('#face-selector')).toBeVisible();
    await expect(page.locator('#face-editor')).toBeVisible();

    for (const person of mockPeople) {
      await expect(page.locator('#face-selector').getByText(person.name)).toBeVisible();
    }
  });

  test('Search filters people by name', async ({ page }) => {
    const asset = selectRandom(fixture.assets, rng);
    await openFaceEditor(page, asset);

    const searchInput = page.locator('#face-selector input');
    await searchInput.fill('Alice');

    await expect(page.locator('#face-selector').getByText('Alice Johnson')).toBeVisible();
    await expect(page.locator('#face-selector').getByText('Bob Smith')).toBeHidden();

    await searchInput.clear();

    for (const person of mockPeople) {
      await expect(page.locator('#face-selector').getByText(person.name)).toBeVisible();
    }
  });

  test('Search with no results shows empty message', async ({ page }) => {
    const asset = selectRandom(fixture.assets, rng);
    await openFaceEditor(page, asset);

    const searchInput = page.locator('#face-selector input');
    await searchInput.fill('Nonexistent Person XYZ');

    for (const person of mockPeople) {
      await expect(page.locator('#face-selector').getByText(person.name)).toBeHidden();
    }
  });

  test('Selecting a person shows confirmation dialog', async ({ page }) => {
    const asset = selectRandom(fixture.assets, rng);
    await openFaceEditor(page, asset);

    const personToTag = mockPeople[0];
    await page.locator('#face-selector').getByText(personToTag.name).click();

    await expect(page.getByRole('dialog')).toBeVisible();
  });

  test('Confirming tag calls createFace API and closes editor', async ({ page }) => {
    const asset = selectRandom(fixture.assets, rng);
    await openFaceEditor(page, asset);

    const personToTag = mockPeople[0];
    await page.locator('#face-selector').getByText(personToTag.name).click();

    await expect(page.getByRole('dialog')).toBeVisible();
    await page.getByRole('button', { name: /confirm/i }).click();

    await expect(page.locator('#face-selector')).toBeHidden();
    await expect(page.locator('#face-editor')).toBeHidden();

    expect(faceCreateCapture.requests).toHaveLength(1);
    expect(faceCreateCapture.requests[0].assetId).toBe(asset.id);
    expect(faceCreateCapture.requests[0].personId).toBe(personToTag.id);
  });

  test('Cancel button closes face editor', async ({ page }) => {
    const asset = selectRandom(fixture.assets, rng);
    await openFaceEditor(page, asset);

    await expect(page.locator('#face-selector')).toBeVisible();
    await expect(page.locator('#face-editor')).toBeVisible();

    await page.getByRole('button', { name: /cancel/i }).click();

    await expect(page.locator('#face-selector')).toBeHidden();
    await expect(page.locator('#face-editor')).toBeHidden();
  });

  test('Selector does not overlap face box on initial open', async ({ page }) => {
    const asset = selectRandom(fixture.assets, rng);
    await openFaceEditor(page, asset);

    const faceBox = await getFaceBoxRect(page);
    const selectorBox = await getSelectorRect(page);
    const overlap = computeOverlapArea(faceBox, selectorBox);

    expect(overlap).toBe(0);
  });

  test('Selector repositions without overlap after dragging face box down', async ({ page }) => {
    const asset = selectRandom(fixture.assets, rng);
    await openFaceEditor(page, asset);

    await dragFaceBox(page, 0, 150);

    const faceBox = await getFaceBoxRect(page);
    const selectorBox = await getSelectorRect(page);
    const overlap = computeOverlapArea(faceBox, selectorBox);

    expect(overlap).toBe(0);
  });

  test('Selector repositions without overlap after dragging face box right', async ({ page }) => {
    const asset = selectRandom(fixture.assets, rng);
    await openFaceEditor(page, asset);

    await dragFaceBox(page, 200, 0);

    const faceBox = await getFaceBoxRect(page);
    const selectorBox = await getSelectorRect(page);
    const overlap = computeOverlapArea(faceBox, selectorBox);

    expect(overlap).toBe(0);
  });

  test('Selector repositions without overlap after dragging face box to top-left corner', async ({ page }) => {
    const asset = selectRandom(fixture.assets, rng);
    await openFaceEditor(page, asset);

    await dragFaceBox(page, -300, -300);

    const faceBox = await getFaceBoxRect(page);
    const selectorBox = await getSelectorRect(page);
    const overlap = computeOverlapArea(faceBox, selectorBox);

    expect(overlap).toBe(0);
  });

  test('Selector repositions without overlap after dragging face box to bottom-right', async ({ page }) => {
    const asset = selectRandom(fixture.assets, rng);
    await openFaceEditor(page, asset);

    await dragFaceBox(page, 300, 300);

    const faceBox = await getFaceBoxRect(page);
    const selectorBox = await getSelectorRect(page);
    const overlap = computeOverlapArea(faceBox, selectorBox);

    expect(overlap).toBe(0);
  });

  test('Selector stays within viewport bounds', async ({ page }) => {
    const asset = selectRandom(fixture.assets, rng);
    await openFaceEditor(page, asset);

    const viewportSize = page.viewportSize()!;
    const selectorBox = await getSelectorRect(page);

    expect(selectorBox.top).toBeGreaterThanOrEqual(0);
    expect(selectorBox.left).toBeGreaterThanOrEqual(0);
    expect(selectorBox.top + selectorBox.height).toBeLessThanOrEqual(viewportSize.height);
    expect(selectorBox.left + selectorBox.width).toBeLessThanOrEqual(viewportSize.width);
  });

  test('Selector stays within viewport after dragging to edge', async ({ page }) => {
    const asset = selectRandom(fixture.assets, rng);
    await openFaceEditor(page, asset);

    await dragFaceBox(page, -400, -400);

    const viewportSize = page.viewportSize()!;
    const selectorBox = await getSelectorRect(page);

    expect(selectorBox.top).toBeGreaterThanOrEqual(0);
    expect(selectorBox.left).toBeGreaterThanOrEqual(0);
    expect(selectorBox.top + selectorBox.height).toBeLessThanOrEqual(viewportSize.height);
    expect(selectorBox.left + selectorBox.width).toBeLessThanOrEqual(viewportSize.width);
  });

  test('Face box is draggable on the canvas', async ({ page }) => {
    const asset = selectRandom(fixture.assets, rng);
    await openFaceEditor(page, asset);

    const beforeDrag = await getFaceBoxRect(page);
    await dragFaceBox(page, 100, 50);
    const afterDrag = await getFaceBoxRect(page);

    expect(afterDrag.left).toBeGreaterThan(beforeDrag.left + 50);
    expect(afterDrag.top).toBeGreaterThan(beforeDrag.top + 20);
  });
});

package face

import (
	"fmt"
	"os"
	"slices"
	"strings"

	"github.com/photoprism/photoprism/pkg/clean"
	"github.com/photoprism/photoprism/pkg/txt"
)

// LicenseAcceptanceVar is the environment variable an operator sets to enable the model weights
// that are gated. One variable covers every model from the same publisher.
const LicenseAcceptanceVar = "INSIGHTFACE_ACCEPT_LICENSE"

// LicenseEligibleEditions lists the editions in which gated model weights may be enabled.
// The installer states what an operator is confirming when they set the acceptance variable.
var LicenseEligibleEditions = []string{"ce", "plus"}

// LicenseGated reports whether the model weights have to be enabled explicitly before use.
func (m *EmbeddingModel) LicenseGated() bool {
	return m != nil && m.WeightLicense() == LicenseNonFree
}

// WeightLicense returns the license of the detector's pretrained weights.
func (d *Detector) WeightLicense() string {
	if d == nil || d.ONNX == nil {
		return ""
	}

	return d.ONNX.License
}

// LicenseGated reports whether the detector weights have to be enabled explicitly before use.
func (d *Detector) LicenseGated() bool {
	return d != nil && d.WeightLicense() == LicenseNonFree
}

// LicenseAccepted reports whether the operator enabled the gated weights.
func LicenseAccepted() bool {
	return txt.Bool(os.Getenv(LicenseAcceptanceVar))
}

// LicenseEligibleEdition reports whether gated weights may be used in the specified edition.
// An edition that is not listed is refused, so a build this predicate does not know about
// cannot enable them by default.
func LicenseEligibleEdition(edition string) bool {
	return slices.Contains(LicenseEligibleEditions, strings.ToLower(strings.TrimSpace(edition)))
}

// LicenseRefused returns why the specified model may not be used in the specified edition, or
// nil when it may. Models whose weights are not gated are always permitted.
func LicenseRefused(name ModelName, edition string) error {
	model := FindEmbeddingModel(name)

	if !model.LicenseGated() {
		return nil
	}

	return licenseRefused(model.Name, edition)
}

// DetectorLicenseRefused returns why the specified detector may not be used in the specified
// edition, or nil when it may. One acceptance covers a publisher rather than a model family,
// so detection and embedding are gated the same way.
func DetectorLicenseRefused(name DetectorName, edition string) error {
	detector := FindDetector(name)

	if !detector.LicenseGated() {
		return nil
	}

	return licenseRefused(detector.Name, edition)
}

// licenseRefused returns why gated weights may not be used in the specified edition, or nil
// when they may.
func licenseRefused(name, edition string) error {
	if !LicenseAccepted() {
		return fmt.Errorf("the %s weights have to be enabled explicitly, "+
			"see the model documentation and set %s=1 to use them", name, LicenseAcceptanceVar)
	}

	if !LicenseEligibleEdition(edition) {
		return fmt.Errorf("the %s weights are not available in the %s edition", name, clean.Log(edition))
	}

	return nil
}

package entity

import (
	"crypto/sha1" //nolint:gosec // G505: Stable non-cryptographic face identifier hash.
	"encoding/base32"
	"encoding/json"
	"fmt"
	"slices"
	"strings"
	"sync"
	"sync/atomic"
	"time"

	"gorm.io/gorm"

	"github.com/photoprism/photoprism/internal/ai/face"
	"github.com/photoprism/photoprism/pkg/clean"
	"github.com/photoprism/photoprism/pkg/dsn"
	"github.com/photoprism/photoprism/pkg/rnd"
)

var faceMutex = sync.Mutex{}

// UpdateFaces reports whether a matching pass changed a cluster, so callers know to refresh.
var UpdateFaces = atomic.Bool{}

// Face represents the face of a Subject.
type Face struct {
	ID              string          `gorm:"type:bytes;size:64;primaryKey;autoIncrement:false;" json:"ID" yaml:"ID"`
	FaceSrc         string          `gorm:"type:bytes;size:8;" json:"Src" yaml:"Src,omitempty"`
	FaceKind        int             `gorm:"size:32" json:"Kind" yaml:"Kind,omitempty"`
	FaceHidden      bool            `json:"Hidden" yaml:"Hidden,omitempty"`
	SubjUID         string          `gorm:"type:bytes;size:42;index;default:'';" json:"SubjUID" yaml:"SubjUID,omitempty"`
	Samples         int             `gorm:"size:32" json:"Samples" yaml:"Samples,omitempty"`
	SampleRadius    float64         `json:"SampleRadius" yaml:"SampleRadius,omitempty"`
	Collisions      int             `gorm:"size:32" json:"Collisions" yaml:"Collisions,omitempty"`
	CollisionRadius float64         `json:"CollisionRadius" yaml:"CollisionRadius,omitempty"`
	MergeRetry      uint8           `gorm:"type:TINYINT(3);size:3;default:0" json:"-" yaml:"-"`
	MergeNotes      string          `gorm:"size:255;default:'';" json:"-" yaml:"-"`
	EmbedModel      string          `gorm:"column:embed_model;type:bytes;size:32;index;default:'';" json:"-" yaml:"EmbedModel,omitempty"`
	EmbeddingJSON   json.RawMessage `gorm:"type:bytes;size:16777215;" json:"-" yaml:"EmbeddingJSON,omitempty"`
	embedding       face.Embedding  `gorm:"-" yaml:"-"`
	// reopened records that this cluster changed after a run read it, so a caller about to stamp
	// it as matched can tell it apart from one that merely started out unmatched - which is the
	// only state the timestamp itself can report, since both are NULL.
	reopened  bool       `gorm:"-" yaml:"-"`
	MatchedAt *time.Time `json:"MatchedAt" yaml:"MatchedAt,omitempty"`
	CreatedAt time.Time  `json:"CreatedAt" yaml:"CreatedAt,omitempty"`
	UpdatedAt time.Time  `json:"UpdatedAt" yaml:"UpdatedAt,omitempty"`
}

// Faceless can be used as argument to match unmatched face markers.
var Faceless = []string{""}

// TableName returns the entity table name.
func (Face) TableName() string {
	return "faces"
}

// NewFace returns a new face for embeddings produced by the specified model.
func NewFace(subjUID, faceSrc string, embeddings face.Embeddings, model face.ModelName) *Face {
	result := &Face{
		SubjUID: subjUID,
		FaceSrc: faceSrc,
	}

	if err := result.SetEmbeddings(embeddings, model); err != nil {
		log.Errorf("face: failed setting embeddings (%s)", err)
	}

	return result
}

// MatchId returns a compound id for matching.
func (m *Face) MatchId(f Face) string {
	if m.ID == "" || f.ID == "" {
		return ""
	}

	if m.ID < f.ID {
		return fmt.Sprintf("%s-%s", m.ID, f.ID)
	} else {
		return fmt.Sprintf("%s-%s", f.ID, m.ID)
	}
}

// SkipMatching checks whether the face should be skipped when matching.
// Only ResolveCollision still raises the kind, to AmbiguousFace.
func (m *Face) SkipMatching() bool {
	return m.FaceKind > 1
}

// SetEmbeddings assigns face embeddings produced by the specified model. The model is
// recorded as passed, so a cluster built from stored vectors keeps their provenance
// instead of adopting whichever model happens to be configured now.
func (m *Face) SetEmbeddings(embeddings face.Embeddings, model face.ModelName) (err error) {
	if len(embeddings) == 0 {
		return fmt.Errorf("invalid embedding")
	}

	// Comparing this cluster with anything the configured model produces would mix two
	// embedding spaces, so it is refused where the row is built rather than where it is read.
	if !face.ModelsComparable(model, face.EmbeddingModelName()) {
		return fmt.Errorf("embedding model %s cannot be compared with %s", clean.Log(model), clean.Log(face.EmbeddingModelName()))
	}

	m.embedding, m.SampleRadius, m.Samples = face.EmbeddingsMidpoint(embeddings)

	// The expected length depends on the configured model, so vectors generated by a
	// different one are rejected rather than mixed into an incompatible vector space.
	// Optimize and merge runs hit this for every legacy cluster after a model switch,
	// so the message has to name the way out.
	if dims := face.ExpectedDims(); len(m.embedding) != dims {
		if current := face.EmbeddingModelName(); current != "" {
			return fmt.Errorf("embedding has %d values, expected %d for model %s, run photoprism faces migrate to regenerate", len(m.embedding), dims, clean.Log(current))
		}

		return fmt.Errorf("embedding has %d values, expected %d", len(m.embedding), dims)
	}

	m.EmbedModel = model

	// A midpoint with no magnitude describes no face and sits one unit from every unit vector, so
	// a cluster built from it would accept whatever a model reaching past 1 compares with it.
	// Refused here as well as in Match, so such a row cannot be stored in the first place - which
	// is also what keeps the recorded kind and the migration predicate in agreement.
	if m.embedding.Zero() {
		return fmt.Errorf("embedding has no magnitude")
	}

	// Classified from the midpoint that is stored, not from the inputs it was computed over: two
	// opposite vectors are each regular while their mean is not a face. Recorded rather than left
	// at zero because the "face:N" search filter reads the number, and raised rather than assigned
	// so a cluster already reported as ambiguous is not downgraded.
	if k := int(m.embedding.Kind()); k > m.FaceKind {
		m.FaceKind = k
	}

	// Limit sample radius to reduce false positives.
	m.SampleRadius = face.ClampSampleRadius(m.SampleRadius)

	// One embedding has no extent, and neither do copies of one crop: the honest value is the
	// numeric tolerance, not the width of a cluster nothing measured. A centroid and a radius are
	// what merging produces, so a singleton carries neither until it becomes part of one.
	if m.SampleRadius <= 0 {
		m.SampleRadius = face.Epsilon
	}

	m.EmbeddingJSON, err = json.Marshal(m.embedding)

	if err != nil {
		return err
	}

	//nolint:gosec // G401: Stable identifier hash; not used for security decisions.
	s := sha1.Sum(m.EmbeddingJSON)

	// Update Face ID and reset match timestamp,
	m.ID = base32.StdEncoding.EncodeToString(s[:])

	m.reopen()

	return nil
}

// Reopened reports whether this cluster changed after the run read it, and therefore has to be
// compared against the markers again rather than stamped as matched.
func (m *Face) Reopened() bool {
	return m != nil && m.reopened
}

// reopen clears the match timestamp and records that this cluster needs comparing again.
func (m *Face) reopen() {
	m.MatchedAt = nil
	m.reopened = true
}

// Matched updates the match timestamp.
func (m *Face) Matched() error {
	m.MatchedAt = TimeStamp()
	return UnscopedDb().Model(m).UpdateColumns(Values{"matched_at": m.MatchedAt}).Error
}

// Embedding returns parsed face embedding.
func (m *Face) Embedding() face.Embedding {
	if len(m.EmbeddingJSON) == 0 {
		return face.Embedding{}
	} else if len(m.embedding) > 0 {
		return m.embedding
	} else if err := json.Unmarshal(m.EmbeddingJSON, &m.embedding); err != nil {
		log.Errorf("failed parsing face embedding json: %s", err)
	}

	return m.embedding
}

// SameEmbeddingModel reports whether the stored embedding can be compared with newly
// generated vectors. Legacy rows without provenance are compatible with FaceNet only.
func (m *Face) SameEmbeddingModel() bool {
	return face.ModelsComparable(m.EmbedModel, face.EmbeddingModelName())
}

// AcceptDist returns the distance below which an embedding joins this cluster.
// The stored radius is clamped on read as well as on write, so a changed cluster
// radius applies to existing rows before a match run rewrites their statistics.
func (m *Face) AcceptDist() float64 {
	return face.AcceptDist(m.SampleRadius)
}

// Match tests if embeddings produced by the specified model match this face.
func (m *Face) Match(embeddings face.Embeddings, model face.ModelName) (match bool, dist float64) {
	dist = -1

	if embeddings.Empty() {
		// No embeddings, no match.
		return false, dist
	}

	// Two models can produce vectors of the same length that mean entirely different
	// things, so provenance decides comparability before any distance is calculated.
	// Both sides are checked: the argument carries its own model, not this cluster's.
	if !m.SameEmbeddingModel() || !face.SameEmbeddingSpace(m.EmbedModel, model) {
		return false, dist
	}

	faceEmbedding := m.Embedding()

	// A cluster with no magnitude is 1 away from every unit embedding, so it accepts whatever a
	// model reaching past 1 compares with it. Refused here as well as where vectors are written,
	// because a row may predate that check.
	if len(faceEmbedding) == 0 || faceEmbedding.Zero() {
		return false, dist
	}

	// Calculate the smallest distance to embeddings.
	dist = embeddings.Dist(faceEmbedding)

	// Any reasons embeddings do not match this face?
	switch {
	case dist < 0:
		// Should never happen.
		return false, dist
	case dist > m.AcceptDist():
		// Too far.
		return false, dist
	case m.CollisionRadius > face.CollisionDist && dist > m.CollisionRadius:
		// Within radius of reported collisions.
		return false, dist
	}

	// If not, at least one of the embeddings match!
	return true, dist
}

// Mergeable reports whether one midpoint can stand for this cluster and the given one, and returns
// the distance between them.
//
// Bounded by what a cluster may ever accept - the widest radius one may hold plus MatchDist - rather
// than by Match, which reads this cluster's own extent and so answers differently depending on which
// of the two is asked. The bound is a constant for that reason, so the verdict stays symmetric.
func (m *Face) Mergeable(f *Face) (mergeable bool, dist float64) {
	dist = -1

	// An id on both sides, or the verdict would depend on the direction asked.
	if m == nil || f == nil || m.ID == "" || f.ID == "" || m.ID == f.ID {
		return false, dist
	}

	// Averaging vectors from two models yields a midpoint that describes neither.
	if !face.SameEmbeddingSpace(m.EmbedModel, f.EmbedModel) {
		return false, dist
	}

	a, b := m.Embedding(), f.Embedding()

	// Refused as in Match: such a midpoint is one unit from every unit vector.
	if len(a) == 0 || len(b) == 0 || a.Zero() || b.Zero() {
		return false, dist
	}

	dist = a.Dist(b)

	// Two faces of one person sit further apart than the link distance far more often than not, so
	// bounding the merge there left hand-labeled clusters waiting indefinitely. The centroid this
	// builds is still measured from its members and clamped where it is stored, so a merged cluster
	// cannot reach past what an automatic one of the same width already reaches.
	return dist >= 0 && dist <= face.AcceptDist(face.ClusterRadius), dist
}

// ResolveCollision resolves a collision with a different subject's face.
func (m *Face) ResolveCollision(embeddings face.Embeddings, model face.ModelName) (resolved bool, err error) {
	if m.SubjUID == "" {
		// Ignore reports for anonymous faces.
		return false, nil
	} else if m.ID == "" {
		return false, fmt.Errorf("invalid face id")
	} else if len(m.EmbeddingJSON) == 0 {
		return false, fmt.Errorf("embedding must not be empty")
	}

	match, dist := m.Match(embeddings, model)
	radius := dist - face.Epsilon

	if !match {
		// Embeddings don't match this face. Ignore.
		return false, nil
	} else if dist < 0 {
		// Should never happen.
		return false, fmt.Errorf("collision distance must be positive")
	} else if dist < face.AmbiguityDist() {
		log.Warnf("faces: %s has ambiguous subject %s with a similar face at dist %f with source %s", m.ID, SubjNames.Log(m.SubjUID), dist, SrcString(m.FaceSrc))

		updatedAt := Now()
		res := UnscopedDb().Model(&Face{}).Where("id = ? AND subj_uid = ?", m.ID, m.SubjUID).
			UpdateColumns(Values{"collisions": gorm.Expr("collisions + 1"), "collision_radius": dist,
				"face_kind": int(face.AmbiguousFace), "updated_at": updatedAt, "matched_at": updatedAt})

		if res.Error != nil {
			return true, res.Error
		} else if res.RowsAffected == 0 {
			m.refreshCollision()
			return false, nil
		}

		m.FaceKind = int(face.AmbiguousFace)
		m.UpdatedAt = updatedAt
		m.MatchedAt = &m.UpdatedAt
		m.Collisions++
		m.CollisionRadius = dist
		UpdateFaces.Store(true)

		return true, nil
	} else if radius <= face.CollisionDist {
		// A radius at or below CollisionDist cannot narrow the cluster, so it is recorded at most
		// once, without reopening the cluster or revising what it holds. The stored row decides, so
		// a copy loaded before a concurrent narrowing cannot widen the cluster.
		if m.CollisionNoted(dist) {
			return false, nil
		}

		res := UnscopedDb().Model(&Face{}).Where("id = ? AND subj_uid = ?", m.ID, m.SubjUID).
			Where("COALESCE(collision_radius, 0) <= ? AND (COALESCE(collision_radius, 0) <= 0 OR collision_radius > ?)", face.CollisionDist, radius).
			UpdateColumns(Values{"collisions": gorm.Expr("collisions + 1"), "collision_radius": radius})

		if res.Error != nil {
			return false, res.Error
		} else if res.RowsAffected == 0 {
			m.refreshCollision()
			return false, nil
		}

		m.Collisions++
		m.CollisionRadius = radius
		UpdateFaces.Store(true)

		return true, nil
	}

	// The stored row decides, so a copy loaded before a concurrent narrowing or a change of person
	// cannot widen the cluster or narrow it against its own person.
	res := UnscopedDb().Model(&Face{}).Where("id = ? AND subj_uid = ?", m.ID, m.SubjUID).
		Where("COALESCE(collision_radius, 0) <= ? OR collision_radius > ?", face.CollisionDist, radius).
		UpdateColumns(Values{"collisions": gorm.Expr("collisions + 1"), "collision_radius": radius, "matched_at": nil, "updated_at": Now()})

	if res.Error != nil {
		return true, res.Error
	} else if res.RowsAffected == 0 {
		m.refreshCollision()
		return false, nil
	}

	// Reopened rather than merely cleared: this narrows the cluster mid-run, and the markers
	// ReviseMatches drops below have nothing to be rematched against if the run then stamps
	// it as matched on its way out.
	m.reopen()
	m.Collisions++
	m.CollisionRadius = radius
	UpdateFaces.Store(true)

	if revised, err := m.ReviseMatches(); err != nil {
		return true, err
	} else if r := len(revised); r > 0 {
		log.Infof("faces: resolved %d conflicts", r)
	}

	return true, nil
}

// refreshCollision reads the stored person and collision fields into this copy, so the checks that
// follow a write conditioned on them decide on the stored row.
func (m *Face) refreshCollision() {
	if stored := FindFace(m.ID); stored != nil {
		m.SubjUID = stored.SubjUID
		m.Collisions = stored.Collisions
		m.CollisionRadius = stored.CollisionRadius
		m.FaceKind = stored.FaceKind
	}
}

// CollisionNoted reports whether a collision at dist, whose radius could not narrow this cluster and
// which is not close enough to make it ambiguous, would change nothing: a radius at or below it is
// recorded already, or the cluster is narrowed further out, which such a radius must not widen.
func (m *Face) CollisionNoted(dist float64) bool {
	radius := dist - face.Epsilon

	if dist < face.AmbiguityDist() || radius > face.CollisionDist {
		return false
	}

	return m.CollisionRadius > face.CollisionDist || m.CollisionRadius > 0 && m.CollisionRadius <= radius
}

// InheritCollision narrows this cluster to the tightest collision bound its sources recorded.
//
// NewFace sets none, so a merged row would otherwise start unbounded and re-earn its narrowing.
// Only ever tightens, since FirstOrCreateFace may return a row already carrying one.
func (m *Face) InheritCollision(from Faces) error {
	radius, collisions := from.CollisionBound(m.SampleRadius)

	if radius == 0 || m.CollisionRadius > face.CollisionDist && m.CollisionRadius <= radius {
		return nil
	}

	m.Collisions, m.CollisionRadius = collisions, radius

	return m.Updates(Values{"collisions": m.Collisions, "collision_radius": m.CollisionRadius})
}

// ClearCollision discards a recorded collision, so the cluster matches at its full accept distance.
//
// A collision records that two subjects competed for the same embeddings. Once an operator states
// they are one person the premise is gone, and the narrowing gates the cluster against faces it
// should hold; a later pass re-derives a collision that is still real.
func (m *Face) ClearCollision() error {
	if m.ID == "" {
		return fmt.Errorf("invalid face id")
	} else if !m.HasCollision() {
		return nil
	}

	m.Collisions = 0
	m.CollisionRadius = 0

	// Reopened so the markers this cluster refused while narrowed are compared against it again;
	// leaving the stamp would keep them out until something else reopened it.
	m.reopen()
	UpdateFaces.Store(true)

	values := Values{"collisions": m.Collisions, "collision_radius": m.CollisionRadius, "matched_at": m.MatchedAt}

	// Only ResolveCollision raises the kind, so a cluster carrying the ambiguous kind was marked by
	// that path and returns to the regular one every cluster is created with. Any other kind is
	// left alone.
	if m.FaceKind == int(face.AmbiguousFace) {
		m.FaceKind = int(face.RegularFace)
		values["face_kind"] = m.FaceKind
	}

	return m.Updates(values)
}

// HasCollision reports whether a narrowing collision is recorded for this cluster.
func (m *Face) HasCollision() bool {
	return m != nil && (m.Collisions > 0 || m.CollisionRadius > 0 || m.FaceKind == int(face.AmbiguousFace))
}

// ClearSubjectCollisions discards the collisions recorded for a subject's clusters and reports how
// many were cleared. Used where two subjects turn out to be one person, since every collision
// between their clusters was recorded against an identity that no longer exists.
func ClearSubjectCollisions(subjUID string) (cleared int, err error) {
	if subjUID == "" {
		return 0, fmt.Errorf("subject has no uid")
	}

	var faces Faces

	if err = UnscopedDb().Where("subj_uid = ?", subjUID).
		Where("collisions > 0 OR collision_radius > 0 OR face_kind = ?", int(face.AmbiguousFace)).
		Find(&faces).Error; err != nil {
		return 0, err
	}

	for i := range faces {
		if clearErr := faces[i].ClearCollision(); clearErr != nil {
			return cleared, clearErr
		}

		cleared++
	}

	return cleared, nil
}

// ReviseMatches releases the markers this cluster no longer matches after its parameters changed.
func (m *Face) ReviseMatches() (revised Markers, err error) {
	if m.ID == "" {
		return revised, fmt.Errorf("empty face id")
	}

	var matches Markers

	if err = Db().Where("face_id = ?", m.ID).Where("marker_type = ?", MarkerFace).
		Find(&matches).Error; err != nil {
		log.Debugf("faces: found no matching markers for conflict resolution (%s)", err)
		return revised, err
	}

	uids := make([]string, 0, len(matches))
	updatedAt := Now()

	for _, marker := range matches {
		// A marker from another embedding space cannot be compared with this cluster,
		// so its assignment is left alone rather than dropped on a comparison that
		// never ran.
		if !face.SameEmbeddingSpace(marker.EmbedModel, m.EmbedModel) {
			continue
		} else if ok, _ := m.Match(marker.Embeddings(), marker.EmbedModel); ok {
			continue
		}

		marker.FaceID = ""
		marker.FaceDist = -1.0
		marker.MatchedAt = nil
		marker.UpdatedAt = updatedAt

		if marker.SubjSrc == SrcAuto {
			marker.SubjUID = ""
		}

		uids = append(uids, marker.MarkerUID)
		revised = append(revised, marker)
	}

	if released, err := m.releaseMarkers(uids, updatedAt); err != nil {
		log.Debugf("faces: failed to remove match with marker (%s)", err) // Conflict resolution
		return nil, err
	} else if released < len(uids) {
		log.Debugf("faces: %d of %d markers were reassigned before release from %s", len(uids)-released, len(uids), m.ID)
	}

	return revised, nil
}

// releaseMarkers detaches the specified markers from this cluster in batches, flags their photos,
// and returns how many it released. Their match stamp is cleared, so the next run compares them
// against every cluster: the cluster narrowed underneath them, and nothing has compared them since.
func (m *Face) releaseMarkers(uids []string, updatedAt time.Time) (released int, err error) {
	if len(uids) == 0 {
		return 0, nil
	}

	UpdateFaces.Store(true)

	for batch := range slices.Chunk(uids, BatchSize()) {
		res := UnscopedDb().Model(&Marker{}).Where("marker_uid IN (?) AND face_id = ?", batch, m.ID).
			UpdateColumns(Values{
				"face_id":    "",
				"face_dist":  -1.0,
				"subj_uid":   gorm.Expr("CASE WHEN subj_src = ? THEN ? ELSE subj_uid END", SrcAuto, ""),
				"matched_at": nil,
				"updated_at": updatedAt,
			})

		if res.Error != nil {
			return released, res.Error
		}

		released += int(res.RowsAffected)

		if err = refreshMarkerPhotos(batch); err != nil {
			return released, err
		}
	}

	return released, nil
}

// whereSameEmbeddingSpace restricts a statement to vectors from the specified model's
// embedding space. An empty name selects the legacy rows that predate the provenance
// column, which is deliberate: the model here is a stored cluster's own, never an
// unknown configuration.
func whereSameEmbeddingSpace(stmt *gorm.DB, model face.ModelName) *gorm.DB {
	switch model {
	case "", face.ModelFaceNet:
		// A vector with no recorded model is FaceNet's, so the two are one space in both
		// directions - which is what face.SameEmbeddingSpace reports and ReviseMatches applies
		// to these same rows. Selecting only the blank ones would leave a legacy cluster unable
		// to attract the markers a loaded embedder has since stamped.
		return stmt.Where("embed_model IN (?)", []string{face.ModelFaceNet, ""})
	default:
		return stmt.Where("embed_model = ?", model)
	}
}

// MatchMarkers finds and references matching markers.
//
// Only the detection floor admits a marker, not the clustering one: the second pass marks faces
// a crowd photograph would lose rather than naming people from them. A marker already in a
// cluster is exempt, or the merge path would strand it on one about to be purged.
func (m *Face) MatchMarkers(faceIds []string) error {
	if len(faceIds) == 0 {
		return nil
	}

	// One embedding may not adopt markers, for the reason it is not offered to the matcher either:
	// it is a labeled example, and one photograph is not evidence enough to name others from. Gated
	// here as well, since this runs once when a cluster is created and the matcher never sees it
	// again.
	if m.Samples < 2 {
		return nil
	}

	var markers Markers

	err := whereSameEmbeddingSpace(Db().
		Where("marker_invalid = FALSE AND marker_type = ? AND face_id IN (?)", MarkerFace, faceIds).
		Where("face_id <> '' OR size >= ?", face.SizeThreshold), m.EmbedModel).
		Find(&markers).Error

	if err != nil {
		log.Debugf("faces: failed fetching markers matching face id %s (%s)", strings.Join(faceIds, ", "), err)
		return err
	}

	start := time.Now()
	resultLen := len(markers)

	for i, marker := range markers {
		if time.Since(start) > time.Duration(time.Minute*15) {
			log.Infof("faces: matching %d of %d markers", i, resultLen)
			start = time.Now()
		}
		if ok, dist := m.Match(marker.Embeddings(), marker.EmbedModel); !ok {
			// Ignore.
		} else if _, err = marker.SetFace(m, dist); err != nil {
			return err
		}
	}

	return nil
}

// UpdateMatchStats widens the extent a cluster reaches after a match run, and never narrows it.
//
// A run visits only the markers that were unmatched when it started, so one face arriving near the
// centroid would otherwise shrink the radius and refuse the members beyond it. It leaves Samples
// alone: that counts the embeddings the centroid was averaged from, which matching does not change.
func (m *Face) UpdateMatchStats(matched int, maxDistance float64) error {
	if m.ID == "" || matched <= 0 {
		return nil
	}

	// The epsilon slack is applied before clamping so it can never lift the stored
	// radius above the configured maximum.
	radius := face.ClampSampleRadius(max(maxDistance+face.Epsilon, m.SampleRadius))

	if m.SampleRadius == radius {
		return nil
	}

	m.SampleRadius = radius
	UpdateFaces.Store(true)

	return m.Updates(Values{"sample_radius": m.SampleRadius})
}

// SetSampleRadius replaces the extent with one measured over the cluster's members, which is what
// makes a smaller value trustworthy where UpdateMatchStats can only widen.
//
// Samples is not touched. The centroid is read rather than recomputed - a cluster's id is its hash -
// so the number of embeddings averaged into it is unchanged however far its members now reach.
func (m *Face) SetSampleRadius(radius float64) error {
	if m.ID == "" || radius <= 0 {
		return nil
	}

	radius = face.ClampSampleRadius(radius)

	if m.SampleRadius == radius {
		return nil
	}

	m.SampleRadius = radius
	UpdateFaces.Store(true)

	return m.Updates(Values{"sample_radius": m.SampleRadius})
}

// SetSubjectUID updates the face's subject uid and related markers.
func (m *Face) SetSubjectUID(subjUid string) (err error) {
	// Update face.
	if err = m.Update("SubjUID", subjUid); err != nil {
		return err
	} else {
		m.SubjUID = subjUid
	}

	UpdateFaces.Store(true)

	// Update related markers.
	if err = Db().Model(&Marker{}).
		Where("face_id = ?", m.ID).
		Where("subj_src = ?", SrcAuto).
		Where("subj_uid <> ?", m.SubjUID).
		Where("marker_invalid = FALSE").
		UpdateColumns(Values{"subj_uid": m.SubjUID, "marker_review": false}).Error; err != nil {
		return err
	}

	return m.RefreshPhotos()
}

// ClaimSubject names this cluster after subjUID while it is still unnamed, and relinks its automatic
// markers while the stored cluster carries that person. It reports whether it does; a person named
// on the cluster after this copy was loaded is kept, and the copy takes it over.
func (m *Face) ClaimSubject(subjUID string) (carries bool, err error) {
	if m.ID == "" {
		return false, fmt.Errorf("empty face id")
	} else if subjUID == "" {
		return false, fmt.Errorf("empty subject uid")
	}

	if res := UnscopedDb().Model(&Face{}).Where("id = ? AND COALESCE(subj_uid, '') = ''", m.ID).
		UpdateColumns(Values{"subj_uid": subjUID, "updated_at": Now()}); res.Error != nil {
		return false, res.Error
	} else if res.RowsAffected == 0 {
		var stored []string

		if err = UnscopedDb().Model(&Face{}).Where("id = ?", m.ID).Pluck("COALESCE(subj_uid, '')", &stored).Error; err != nil {
			return false, err
		} else if len(stored) == 0 {
			return false, nil
		} else if stored[0] != subjUID {
			m.SubjUID = stored[0]
			return false, nil
		}
	}

	m.SubjUID = subjUID
	UpdateFaces.Store(true)

	if err = UnscopedDb().Model(&Marker{}).
		Where("face_id = ?", m.ID).
		Where("subj_src = ?", SrcAuto).
		Where("subj_uid <> ?", subjUID).
		Where("marker_invalid = FALSE").
		Where(fmt.Sprintf("EXISTS (SELECT 1 FROM %s f WHERE f.id = ? AND f.subj_uid = ?)", Face{}.TableName()), m.ID, subjUID).
		UpdateColumns(Values{"subj_uid": subjUID, "marker_review": false}).Error; err != nil {
		return true, err
	}

	return true, m.RefreshPhotos()
}

// RefreshPhotos flags related photos for metadata maintenance.
func (m *Face) RefreshPhotos() error {
	if m.ID == "" {
		return fmt.Errorf("empty face id")
	}

	UpdateFaces.Store(true)

	var err error
	switch DbDialect() {
	case dsn.DialectMySQL:
		update := fmt.Sprintf(`UPDATE photos p JOIN files f ON f.photo_id = p.id JOIN %s m ON m.file_uid = f.file_uid
			SET p.checked_at = NULL WHERE m.face_id = ?`, Marker{}.TableName())
		err = UnscopedDb().Exec(update, m.ID).Error
	default:
		update := fmt.Sprintf(`UPDATE photos SET checked_at = NULL WHERE id IN (SELECT f.photo_id FROM files f
			JOIN %s m ON m.file_uid = f.file_uid WHERE m.face_id = ?)`, Marker{}.TableName())
		err = UnscopedDb().Exec(update, m.ID).Error
	}

	return err
}

// Hide hides the face by default.
func (m *Face) Hide() (err error) {
	return m.Update("FaceHidden", true)
}

// Show shows the face by default.
func (m *Face) Show() (err error) {
	return m.Update("FaceHidden", false)
}

// Create inserts the face to the database.
func (m *Face) Create() error {
	if m.ID == "" {
		return fmt.Errorf("empty id")
	}

	faceMutex.Lock()
	defer faceMutex.Unlock()

	UpdateFaces.Store(true)

	return Db().Create(m).Error
}

// Delete removes the face from the database.
func (m *Face) Delete() error {
	if m.ID == "" {
		return fmt.Errorf("empty id")
	}

	UpdateFaces.Store(true)

	// Remove face id from markers before deleting.
	if err := Db().Model(&Marker{}).
		Where("face_id = ?", m.ID).
		UpdateColumns(Values{"face_id": "", "face_dist": -1}).Error; err != nil {
		return err
	}

	return Db().Delete(m).Error
}

// Update a face property in the database.
func (m *Face) Update(attr string, value any) error {
	if m.ID == "" {
		return fmt.Errorf("empty id")
	}

	UpdateFaces.Store(true)

	return UnscopedDb().Model(m).Update(attr, value).Error
}

// Updates face properties in the database.
func (m *Face) Updates(values any) error {
	if m.ID == "" {
		return fmt.Errorf("empty id")
	}

	UpdateFaces.Store(true)

	return UnscopedDb().Model(m).Updates(values).Error
}

// FirstOrCreateFace returns the existing entity, inserts a new entity or nil in case of errors.
func FirstOrCreateFace(m *Face) *Face {
	if m == nil {
		return nil
	}

	if m.ID == "" {
		return nil
	}

	result := Face{}

	// Search existing face with the same ID. Report if found and it belongs to another person.
	if findErr := UnscopedDb().Where("id = ?", m.ID).First(&result).Error; findErr == nil && result.ID != "" {
		if m.SubjUID != result.SubjUID {
			log.Warnf("faces: %s has ambiguous subjects %s and %s", m.ID, SubjNames.Log(m.SubjUID), SubjNames.Log(result.SubjUID))
		}
		return &result
	} else if err := m.Create(); err == nil {
		UpdateFaces.Store(true)
		return m
	} else if findErr = UnscopedDb().Where("id = ?", m.ID).First(&result).Error; findErr == nil && result.ID != "" {
		if m.SubjUID != result.SubjUID {
			log.Warnf("faces: %s has ambiguous subjects %s and %s", m.ID, SubjNames.Log(m.SubjUID), SubjNames.Log(result.SubjUID))
		}
		return &result
	} else {
		log.Errorf("faces: failed to add %s (%s)", m.ID, err)
	}

	return nil
}

// FindFace returns an existing entity if exists.
func FindFace(id string) *Face {
	if id == "" {
		return nil
	}

	f := Face{}

	if err := Db().Where("id = ?", strings.ToUpper(id)).First(&f).Error; err != nil {
		return nil
	}

	return &f
}

// ValidFaceCount counts the number of valid face markers for a file uid.
func ValidFaceCount(fileUid string) (c int) {
	if !rnd.IsUID(fileUid, FileUID) {
		return
	}

	var count int64

	if err := Db().Model(&Marker{}).
		Where("file_uid = ? AND marker_type = ?", fileUid, MarkerFace).
		Where("marker_invalid = FALSE").
		Count(&count).Error; err != nil {
		log.Errorf("file: %s (count faces)", err)
		return 0
	} else {
		return int(count)
	}
}

package face

import (
	"testing"

	"github.com/stretchr/testify/assert"
	"github.com/stretchr/testify/require"
)

func TestEmbeddingModel_LicenseGated(t *testing.T) {
	t.Run("ResearchOnly", func(t *testing.T) {
		assert.True(t, FindEmbeddingModel(ModelArcFaceR50).LicenseGated())
		assert.True(t, FindEmbeddingModel(ModelArcFaceMBF).LicenseGated())
	})
	t.Run("Permissive", func(t *testing.T) {
		assert.False(t, FindEmbeddingModel(ModelSFace).LicenseGated())
		assert.False(t, FindEmbeddingModel(ModelAuraFace).LicenseGated())
	})
	t.Run("UnknownLicense", func(t *testing.T) {
		// FaceNet's weight provenance was never verified, which is not the same as gated.
		assert.False(t, FindEmbeddingModel(ModelFaceNet).LicenseGated())
	})
	t.Run("NilModel", func(t *testing.T) {
		assert.False(t, (*EmbeddingModel)(nil).LicenseGated())
	})
}

func TestLicenseAccepted(t *testing.T) {
	t.Run("Unset", func(t *testing.T) {
		t.Setenv(LicenseAcceptanceVar, "")
		assert.False(t, LicenseAccepted())
	})
	t.Run("Accepted", func(t *testing.T) {
		t.Setenv(LicenseAcceptanceVar, "1")
		assert.True(t, LicenseAccepted())
	})
	t.Run("Refused", func(t *testing.T) {
		t.Setenv(LicenseAcceptanceVar, "0")
		assert.False(t, LicenseAccepted())
	})
}

func TestLicenseEligibleEdition(t *testing.T) {
	t.Run("Eligible", func(t *testing.T) {
		assert.True(t, LicenseEligibleEdition("ce"))
		assert.True(t, LicenseEligibleEdition(" Plus "))
	})
	t.Run("Ineligible", func(t *testing.T) {
		assert.False(t, LicenseEligibleEdition("pro"))
		assert.False(t, LicenseEligibleEdition("portal"))
	})
	t.Run("Unknown", func(t *testing.T) {
		// An edition this predicate does not know about must not enable gated weights.
		assert.False(t, LicenseEligibleEdition(""))
		assert.False(t, LicenseEligibleEdition("enterprise"))
	})
}

func TestLicenseRefused(t *testing.T) {
	t.Run("Ungated", func(t *testing.T) {
		assert.NoError(t, LicenseRefused(ModelSFace, "pro"))
		assert.NoError(t, LicenseRefused(ModelFaceNet, "portal"))
	})
	t.Run("UnknownModel", func(t *testing.T) {
		assert.NoError(t, LicenseRefused("dlib", "ce"))
	})
	t.Run("NotAccepted", func(t *testing.T) {
		t.Setenv(LicenseAcceptanceVar, "")
		err := LicenseRefused(ModelArcFaceR50, "ce")

		require.Error(t, err)
		assert.Contains(t, err.Error(), LicenseAcceptanceVar)
	})
	t.Run("AcceptedAndEligible", func(t *testing.T) {
		t.Setenv(LicenseAcceptanceVar, "1")
		assert.NoError(t, LicenseRefused(ModelArcFaceR50, "ce"))
		assert.NoError(t, LicenseRefused(ModelArcFaceMBF, "plus"))
	})
	t.Run("AcceptedButIneligible", func(t *testing.T) {
		t.Setenv(LicenseAcceptanceVar, "1")
		err := LicenseRefused(ModelArcFaceR50, "pro")

		require.Error(t, err)
		assert.Contains(t, err.Error(), "pro edition")
	})
}

func TestDetectorLicenseRefused(t *testing.T) {
	t.Run("Ungated", func(t *testing.T) {
		assert.NoError(t, DetectorLicenseRefused(DetectorYuNet, "pro"))
	})
	t.Run("UnknownDetector", func(t *testing.T) {
		assert.NoError(t, DetectorLicenseRefused("centerface", "ce"))
	})
	t.Run("NotAccepted", func(t *testing.T) {
		t.Setenv(LicenseAcceptanceVar, "")
		err := DetectorLicenseRefused(DetectorSCRFD, "ce")

		require.Error(t, err)
		assert.Contains(t, err.Error(), LicenseAcceptanceVar)
	})
	t.Run("AcceptedAndEligible", func(t *testing.T) {
		t.Setenv(LicenseAcceptanceVar, "1")
		assert.NoError(t, DetectorLicenseRefused(DetectorSCRFD, "ce"))
		assert.NoError(t, DetectorLicenseRefused(DetectorSCRFD, "plus"))
	})
	t.Run("AcceptedButIneligible", func(t *testing.T) {
		// One acceptance covers the publisher, so the detector is refused where the
		// embedding weights are.
		t.Setenv(LicenseAcceptanceVar, "1")
		err := DetectorLicenseRefused(DetectorSCRFD, "portal")

		require.Error(t, err)
		assert.Contains(t, err.Error(), "portal edition")
	})
}

